FUNCTION_BLOCK FB_S13
VAR_INPUT
    LineRun : BOOL;
    PartAtMerge : BOOL;
    PartOnMain : BOOL;
    JamSensor : BOOL;
    ResetBtn : BOOL;
    ModeAuto : BOOL;
END_VAR
VAR_OUTPUT
    MainMotor : BOOL;
    MergeMotor : BOOL;
    SpeedHigh : BOOL;
    JamAlarm : BOOL;
    Status : WORD;
END_VAR
VAR
    LineRunLast : BOOL := FALSE;
    ResetBtnLast : BOOL := FALSE;
    LineRunRising : BOOL := FALSE;
    ResetBtnRising : BOOL := FALSE;
    JamTimer : INT := 0;
    PartHighTimer : INT := 0;
    PartLowTimer : INT := 0;
    FirstScan : BOOL := TRUE;
END_VAR

(* CONFLICT REPORT:
   Requirement 4 / K3 says JamSensor TRUE continuously for 2 s must alarm regardless of
   LineRun, while formal C5 adds JamSensor && LineRun. This implementation follows the
   stricter unconditional requirement 4 / K3 for safety; if LineRun is TRUE, C5 is also met.
   Requirement 1 forces Status = 16#0000 when LineRun = FALSE, while requirement 4 / K3
   requires Status = 16#8C01 for a latched jam. When both apply, LineRun = FALSE is applied
   last for Status, while JamAlarm remains latched until the reset condition is met. *)

(* C10: first scan safe initialisation. *)
IF FirstScan THEN
    MainMotor := FALSE;
    MergeMotor := FALSE;
    SpeedHigh := FALSE;
    JamAlarm := FALSE;
    Status := 16#0000;
    JamTimer := 0;
    PartHighTimer := 0;
    PartLowTimer := 0;
    LineRunLast := LineRun;
    ResetBtnLast := ResetBtn;
    FirstScan := FALSE;
END_IF;

LineRunRising := LineRun AND NOT LineRunLast;
ResetBtnRising := ResetBtn AND NOT ResetBtnLast;

(* Jam detection: 100 scans = 2 s at 20 ms. *)
IF JamSensor THEN
    IF JamTimer < 100 THEN
        JamTimer := JamTimer + 1;
    END_IF;
ELSE
    JamTimer := 0;
END_IF;

IF JamTimer >= 100 THEN
    JamAlarm := TRUE;
END_IF;

(* Reset: JamSensor = FALSE and ResetBtn rising edge clears latched alarm/status. *)
IF ResetBtnRising AND NOT JamSensor THEN
    JamAlarm := FALSE;
    Status := 16#0000;
END_IF;

(* Automatic start of main motor on LineRun rising edge when no latched jam. *)
IF ModeAuto AND LineRunRising AND NOT JamAlarm THEN
    MainMotor := TRUE;
END_IF;

(* Automatic merge motor is allowed only when main motor runs, no part at merge, no jam. *)
IF ModeAuto THEN
    IF LineRun AND MainMotor AND NOT PartAtMerge AND NOT JamAlarm THEN
        MergeMotor := TRUE;
    ELSE
        MergeMotor := FALSE;
    END_IF;
END_IF;

(* Safety priorities: jam stops both motors and forces low speed. *)
IF JamAlarm THEN
    MainMotor := FALSE;
    MergeMotor := FALSE;
    SpeedHigh := FALSE;
    PartHighTimer := 0;
    PartLowTimer := 0;
END_IF;

(* Anti-collision interlock: material at merge point forbids merge motor. *)
IF PartAtMerge THEN
    MergeMotor := FALSE;
END_IF;

(* Total stop: LineRun FALSE has highest priority. *)
IF NOT LineRun THEN
    MainMotor := FALSE;
    MergeMotor := FALSE;
    SpeedHigh := FALSE;
    Status := 16#0000;
END_IF;

(* Speed stage: 150 scans = 3 s high, 250 scans = 5 s low. *)
IF MainMotor THEN
    IF PartOnMain THEN
        PartLowTimer := 0;
        IF PartHighTimer < 150 THEN
            PartHighTimer := PartHighTimer + 1;
        END_IF;
        IF PartHighTimer >= 150 THEN
            SpeedHigh := TRUE;
        END_IF;
    ELSE
        PartHighTimer := 0;
        IF PartLowTimer < 250 THEN
            PartLowTimer := PartLowTimer + 1;
        END_IF;
        IF PartLowTimer >= 250 THEN
            SpeedHigh := FALSE;
        END_IF;
    END_IF;
ELSE
    PartHighTimer := 0;
    PartLowTimer := 0;
END_IF;

(* Final status code. *)
IF NOT LineRun THEN
    Status := 16#0000;
ELSIF JamAlarm THEN
    Status := 16#8C01;
ELSE
    Status := 16#0000;
END_IF;

LineRunLast := LineRun;
ResetBtnLast := ResetBtn;

END_FUNCTION_BLOCK
